using System.Text;
using Broiler.JavaScript.Runtime.Unicode;
using Broiler.Unicode.Algorithms;
using Broiler.Unicode.Generation;

namespace Broiler.JavaScript.Runtime.Tests;

/// <summary>
/// The Unicode tables this engine embeds (milestone SJL-7.5, decision SJL-D-6 (c)): generated by the owner's
/// generator, the test-only package <c>Broiler.Unicode.Generation</c>, from this repository's pin, and held
/// byte for byte here (the shared JavaScript libraries programme's rule SL7, in its shape for this engine),
/// with its negative controls.
/// </summary>
public sealed class UnicodeTableRegenerationTests
{
    /// <summary>The five case-folding tables, which this engine does not read and does not embed.</summary>
    internal static readonly UnicodeTable[] FoldingTables =
    [
        UnicodeTable.FoldingLayout,
        UnicodeTable.FoldData,
        UnicodeTable.OrbitIndex,
        UnicodeTable.UpperData,
        UnicodeTable.UpperOrbitIndex,
    ];

    [Fact]
    public void The_embedded_tables_regenerate_byte_for_byte_from_the_pin()
    {
        var desired = UnicodeArchive.TableSource(UnicodeArchive.Embedded(UnicodeArchive.Tables));
        var path = UnicodeArchive.Full(UnicodeArchive.TableSourcePath);

        if (string.Equals(Environment.GetEnvironmentVariable(UnicodeArchive.WriteVariable), "1", StringComparison.Ordinal))
            File.WriteAllText(path, desired, new UTF8Encoding(false));

        var committed = File.ReadAllText(path);

        Assert.True(
            string.Equals(committed, desired, StringComparison.Ordinal),
            Stale(committed, desired) ?? "the committed tables differ from what the generator writes");
    }

    [Fact]
    public void Two_generations_write_the_same_bytes()
    {
        var again = UnicodeTableGenerator.Generate(UnicodeArchive.Pin, UnicodeArchive.Read(UnicodeArchive.Pin));

        Assert.Equal(UnicodeArchive.Tables.Select(static pair => pair.Key), again.Select(static pair => pair.Key));

        foreach (var ((table, first), (_, second)) in UnicodeArchive.Tables.Zip(again))
            Assert.True(first.AsSpan().SequenceEqual(second), $"{table} differs between two generations");
    }

    [Fact]
    public void The_pin_equals_the_owner_s_by_file_name_length_and_hash()
    {
        Assert.Empty(UnicodePin.Owner().Differences(UnicodeArchive.Pin));
        Assert.Equal(26, UnicodeArchive.Pin.Entries.Count);
        Assert.Equal(UnicodePin.PinnedVersion, UnicodeArchive.Pin.Version);
    }

    [Fact]
    public void The_provider_answers_the_generated_bytes_for_every_table_but_the_folding_tables()
    {
        var provider = JSUnicode.Tables;

        Assert.Equal("17.0.0", provider.UnicodeVersion);
        Assert.Equal(UnicodeAlgorithms.UnicodeVersion, provider.UnicodeVersion);

        foreach (var (table, bytes) in UnicodeArchive.Tables)
        {
            if (FoldingTables.Contains(table))
            {
                Assert.True(provider.Table(table).IsEmpty, $"{table} is embedded, and this engine does not read it");
                continue;
            }

            Assert.True(bytes.Length > 0, $"{table} is empty");
            Assert.True(provider.Table(table).SequenceEqual(bytes), $"{table} differs from the generator's output");
        }

        Assert.True(provider.Table(UnicodeTable.None).IsEmpty);
    }

    [Fact]
    public void Every_owner_type_this_engine_reads_constructs_over_the_provider_and_folding_does_not()
    {
        var provider = JSUnicode.Tables;

        Assert.NotNull(new UnicodeProperties(provider));
        Assert.NotNull(new EcmaScriptLexical(new UnicodeProperties(provider)));
        Assert.NotNull(new UnicodeCaseMapping(provider));
        Assert.NotNull(new UnicodeNormalization(provider));
        Assert.NotNull(new UnicodeStringProperties(provider));
        Assert.NotNull(JSUnicode.Properties);
        Assert.NotNull(JSUnicode.Lexical);
        Assert.NotNull(JSUnicode.CaseMapping);
        Assert.NotNull(JSUnicode.Normalization);
        Assert.NotNull(JSUnicode.StringProperties);
        Assert.NotNull(new Broiler.Unicode.Segmentation.UnicodeSegmenter(provider));

        // By design: the folding tables are not embedded, and the owner refuses a provider that lacks one.
        Assert.Throws<ArgumentException>(() => new UnicodeCaseFolding(provider));
    }

    [Fact]
    public void Control_a_changed_byte_of_the_committed_tables_is_reported_with_its_table()
    {
        var desired = UnicodeArchive.TableSource(UnicodeArchive.Embedded(UnicodeArchive.Tables));
        var marker = "private static ReadOnlySpan<byte> CasedRanges => new byte[]";
        var at = desired.IndexOf(marker, StringComparison.Ordinal);
        var digit = desired.IndexOfAny("0123456789".ToCharArray(), desired.IndexOf('{', at) + 1);
        var changed = desired[..digit] + (desired[digit] == '9' ? '8' : (char)(desired[digit] + 1)) + desired[(digit + 1)..];

        Assert.NotEqual(desired, changed);
        Assert.Contains("CasedRanges", Stale(changed, desired), StringComparison.Ordinal);
    }

    [Fact]
    public void Control_a_changed_hash_in_the_pin_is_refused_before_anything_is_written()
    {
        var text = File.ReadAllText(UnicodeArchive.Full(UnicodeArchive.PinPath));
        var line = text.Split('\n').First(static line => line.StartsWith("file ucd-17.0.0/CaseFolding.txt ", StringComparison.Ordinal));
        var hash = line.Split(' ')[3];
        var changedHash = (hash[0] == '0' ? '1' : '0') + hash[1..];
        var changed = UnicodePin.Parse(text.Replace(line, line.Replace(hash, changedHash, StringComparison.Ordinal), StringComparison.Ordinal));

        var refusal = Assert.Throws<InvalidDataException>(() => UnicodeTableGenerator.Generate(changed, UnicodeArchive.Files));

        Assert.Contains("ucd-17.0.0/CaseFolding.txt hashes to", refusal.Message, StringComparison.Ordinal);
        Assert.NotEmpty(UnicodePin.Owner().Differences(changed));
    }

    [Fact]
    public void Control_a_changed_byte_of_a_pinned_input_is_refused()
    {
        var copy = new Dictionary<string, byte[]>(UnicodeArchive.Files, StringComparer.Ordinal);
        var bytes = (byte[])copy["ucd-17.0.0/UnicodeData.txt"].Clone();

        bytes[100] ^= 1;
        copy["ucd-17.0.0/UnicodeData.txt"] = bytes;

        var refusal = Assert.Throws<InvalidDataException>(() => UnicodeTableGenerator.Generate(UnicodeArchive.Pin, copy));

        Assert.Contains("ucd-17.0.0/UnicodeData.txt hashes to", refusal.Message, StringComparison.Ordinal);
    }

    /// <summary>Where the committed text first parts from the desired one, and the table it is in; null when they agree.</summary>
    private static string? Stale(string committed, string desired)
    {
        if (string.Equals(committed, desired, StringComparison.Ordinal))
            return null;

        var current = committed.Split('\n');
        var wanted = desired.Split('\n');
        var line = Enumerable.Range(0, Math.Min(current.Length, wanted.Length))
            .FirstOrDefault(index => !string.Equals(current[index], wanted[index], StringComparison.Ordinal), Math.Min(current.Length, wanted.Length));
        var table = wanted.Take(line + 1).LastOrDefault(static text => text.Contains("private static ReadOnlySpan<byte> ", StringComparison.Ordinal))
            ?.Trim().Split(' ')[3] ?? "the file's head";

        return $"{UnicodeArchive.TableSourcePath} is not what the generator writes: first difference at line {line + 1}, in {table}. " +
            $"Change the generator or the pin and run with {UnicodeArchive.WriteVariable}=1; never edit the file.";
    }
}

/// <summary>
/// This repository's pinned Unicode archive, read off disk by the pin's own list, and the tables the owner's
/// generator writes from it, computed once per test run.
/// </summary>
internal static class UnicodeArchive
{
    /// <summary>The pin, relative to the repository root.</summary>
    internal const string PinPath = "data/unicode/pins/unicode.pin";

    /// <summary>The embedded tables' C# source, relative to the repository root.</summary>
    internal const string TableSourcePath = "Broiler.JS/Broiler.JavaScript.Runtime/Unicode/JSUnicodeTableData.g.cs";

    /// <summary>Set to <c>1</c> to make the regeneration test write rather than assert.</summary>
    internal const string WriteVariable = "BROILER_JS_UNICODE_WRITE";

    private static readonly Lazy<string> root = new(static () =>
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
        {
            if (File.Exists(Path.Combine(directory.FullName, "Broiler.JS.slnx")))
                return directory.FullName;
        }

        throw new InvalidOperationException("No Broiler.JS.slnx above the test's directory.");
    });

    private static readonly Lazy<UnicodePin> pin = new(static () => UnicodePin.Parse(File.ReadAllText(Full(PinPath))));

    private static readonly Lazy<IReadOnlyDictionary<string, byte[]>> files = new(static () => Read(Pin));

    private static readonly Lazy<IReadOnlyList<KeyValuePair<UnicodeTable, byte[]>>> tables =
        new(static () => UnicodeTableGenerator.Generate(Pin, Files));

    /// <summary>The pin on disk.</summary>
    internal static UnicodePin Pin => pin.Value;

    /// <summary>Every pinned file's bytes, by the name the pin writes it under.</summary>
    internal static IReadOnlyDictionary<string, byte[]> Files => files.Value;

    /// <summary>Every table the generator writes.</summary>
    internal static IReadOnlyList<KeyValuePair<UnicodeTable, byte[]>> Tables => tables.Value;

    /// <summary>The comment lines the generated C# file opens with.</summary>
    internal static readonly string[] SourceHeader =
    [
        "GENERATED by Broiler.Unicode.Generation from the Unicode Character Database 17.0.0 files, the",
        "auxiliary break data, the emoji sequence files and the ECMAScript property tables that",
        "data/unicode/pins/unicode.pin names, every table but the five case-folding tables, which this",
        "engine does not read. Broiler.JavaScript.Runtime.Tests regenerates this file and compares it byte",
        "for byte (the shared JavaScript libraries programme's rule SL7), so a change belongs in the",
        "generator or the pin and never here: run UnicodeTableRegenerationTests with",
        "BROILER_JS_UNICODE_WRITE=1.",
        string.Empty,
        "The table data is derived from Unicode data files and is subject to the Unicode License v3 (SPDX",
        "Unicode-3.0), whose text THIRD_PARTY_NOTICES.md carries.",
    ];

    /// <summary>The tables this engine embeds: every one the generator writes but the folding tables.</summary>
    internal static IReadOnlyList<KeyValuePair<UnicodeTable, byte[]>> Embedded(IReadOnlyList<KeyValuePair<UnicodeTable, byte[]>> generated) =>
        generated.Where(static pair => !UnicodeTableRegenerationTests.FoldingTables.Contains(pair.Key)).ToList();

    /// <summary>The C# source the generator writes for this engine's tables.</summary>
    internal static string TableSource(IReadOnlyList<KeyValuePair<UnicodeTable, byte[]>> embedded) =>
        UnicodeTableSource.Write(embedded, "Broiler.JavaScript.Runtime.Unicode", "JSUnicodeTableData", SourceHeader);

    /// <summary>A path relative to the repository root, made absolute.</summary>
    internal static string Full(string relativePath) =>
        Path.Combine(root.Value, relativePath.Replace('/', Path.DirectorySeparatorChar));

    /// <summary>Reads every file a pin names off disk: a <c>file</c> beside the pin, a <c>spec-table</c> from the root.</summary>
    internal static IReadOnlyDictionary<string, byte[]> Read(UnicodePin source)
    {
        var directory = Path.GetDirectoryName(Full(PinPath))!;

        return source.Entries.ToDictionary(
            static entry => entry.Name,
            entry => File.ReadAllBytes(entry.Kind == "file"
                ? Path.Combine(directory, entry.Name.Replace('/', Path.DirectorySeparatorChar))
                : Full(entry.Name)),
            StringComparer.Ordinal);
    }
}
